                        .some(p => p.includes(nd.id)); const pr = Math.min(1, (nd.power || 0) / this.maxPower); const sz =
                        7 + pr * 16; const ob = Math.min(7, (nd.oppCount || 0) * 1.8); const ts = sz + ob; const glow = ctx
