  <div id="pumpLaunchModal" class="modal"><div class="modal-content"><h3>🚀 LAUNCH ON PUMP.FUN (Testnet)</h3><div><label>Token Name:</label><input type="text" id="pumpTokenName" placeholder="My Token" style="width:150px;"><label>Symbol:</label><input type="text" id="pumpTokenSymbol" placeholder="TKN" style="width:80px;"></div><div><label>Description:</label><input type="text" id="pumpTokenDesc" placeholder="A meme coin" style="width:200px;"></div><div><label>Image URL:</label><input type="text" id="pumpTokenImage" placeholder="https://..." style="width:200px;"></div><div><label>Pump.fun API:</label><input type="text" id="pumpApiUrl" value="https://frontend-api.pump.fun" style="width:200px;"></div><div><small style="color:var(--cyan);">Launches a simulated token on Pump.fun (paper). Live would require wallet signature.</small></div><div style="margin-top:8px;"><button onclick="closePumpLaunchModal()">CANCEL</button><button id="pumpLaunchBtn" class="cyan">🚀 LAUNCH</button></div></div></div>
  <div id="apiKeysModal" class="modal"><div class="modal-content"><h3>🔑 API KEYS</h3><div id="apiKeyList" class="checkbox-group" style="flex-direction:column;align-items:flex-start;"></div><button onclick="saveApiKeysFromModal()" class="cyan">SAVE</button><button onclick="closeApiKeysModal()">CLOSE</button></div></div>

  <script>
    // ─── Version & Persistence Key ──────────────────
    const APP_VERSION = '22.30';
    const STORAGE_KEY = `qfoam_v${APP_VERSION}`;

    // ─── Audio context ──────────────────────────────
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    function playTone(f, d, t = 'square', v = 0.05) {
      const o = audioCtx.createOscillator(), g = audioCtx.createGain();
      o.type = t; o.frequency.value = f;
      g.gain.setValueAtTime(v, audioCtx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + d);
      o.connect(g); g.connect(audioCtx.destination);
      o.start(); o.stop(audioCtx.currentTime + d);
    }
    function playSpin() { playTone(800, 0.08, 'sawtooth', 0.04); }
    function playWin() { playTone(523, 0.08); setTimeout(() => playTone(659, 0.08), 80); setTimeout(() => playTone(784, 0.15), 160); }

    // ─── Particle effects ───────────────────────────
    const canvas = document.getElementById('particleCanvas'), ctx = canvas.getContext('2d');
    let particles = [];
    function resize() { canvas.width = innerWidth; canvas.height = innerHeight; }
    window.addEventListener('resize', resize);
    resize();
    class Particle {
      constructor(x, y, vx, vy, c, l) { this.x = x; this.y = y; this.vx = vx; this.vy = vy; this.color = c; this.life = l; }
    }
    function anim() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx; p.y += p.vy; p.vy += 0.05; p.life -= 0.012;
        ctx.fillStyle = p.color; ctx.globalAlpha = Math.max(0, p.life);
        ctx.fillRect(p.x, p.y, 3, 3);
        if (p.life <= 0) particles.splice(i, 1);
      }
      requestAnimationFrame(anim);
    }
    anim();
    function confetti(x, y, n = 25) {
      const cols = ['#ff00ff','#00ff00','#ffd700','#00f0ff'];
      for (let i = 0; i < n; i++) particles.push(new Particle(x, y, (Math.random()-0.5)*7, (Math.random()-0.5)*6-3, cols[Math.floor(Math.random()*cols.length)], 0.5+Math.random()*0.4));
    }

    // ─── UI Scale ───────────────────────────────────
    function setUIScale(val) {
      document.documentElement.style.setProperty('--base-font-size', val + 'px');
      document.getElementById('uiScaleLabel').textContent = val + 'px';
      localStorage.setItem('uiScale', val);
    }

    // ─── Global State ──────────────────────────────
    const State = {
      bankroll: 10000,
      paperMatrix: 0,
      liveMatrix: 0,
      paperLevel: 1,
      liveLevel: 1,
      get matrix() { return this.liveMode ? this.liveMatrix : this.paperMatrix; },
      set matrix(v) { if (this.liveMode) this.liveMatrix = v; else this.paperMatrix = v; },
      get level() { return this.liveMode ? this.liveLevel : this.paperLevel; },
      set level(v) { if (this.liveMode) this.liveLevel = v; else this.paperLevel = v; },
      qFund: 0,
      lFund: 0,
      liveMode: false,
      liveTestMode: false,
      userCoins: [],
      exchanges: {},
      allPairs: [],
      graph: {},
      triangles: [],
      opportunities: { mega: [], triangular: [], bellman: [], suspicious: [] },
      stats: { totalPairs:0, graphNodes:0, graphEdges:0, triangleCount:0, wsBytes:0, oppCount:0, wsReconnects:0 },
      selectedIntraExchanges: new Set(),
      selectedFiats: new Set(['RUB','INR','EUR','GBP']),
      liveScanInterval: null,
      liveScanActive: false,
      forexRates: {},
      forexInterval: null,
      wsTickers: {},
      wsConnections: {},
      tradeLedger: [],
      liveTradeHistory: [],
      proxyMode: 'direct',
      customProxyUrl: '',
      execPath: '/execute',
      lastTradeExecTime: 0,
      lastPullTime: 0,
      lastCoinCreateTime: 0,
      graphRenderer: null,
      purchasePower: {},
      highlightedPaths: [],
      conflictEdges: new Set(),
      basketHoldings: {},
      acquisitionPaths: {},
      batchHistory: [],
      coinExchangeList: ['QUANTM_DEX'],
      operationLatency: [],
      testnetsActive: false,
      pauseLogs: false,
      logBuffer: [],
      apiKeys: {},
      coinLevels: {},

      load() {
        try {
          const s = JSON.parse(localStorage.getItem(STORAGE_KEY));
          if (s) {
            this.bankroll = s.bankroll || 10000;
            this.paperMatrix = s.paperMatrix || 0;
            this.liveMatrix = s.liveMatrix || 0;
            this.paperLevel = s.paperLevel || 1;
            this.liveLevel = s.liveLevel || 1;
            this.liveMode = s.liveMode || false;
            this.liveTestMode = s.liveTestMode || false;
            this.userCoins = s.userCoins || [];
            this.selectedIntraExchanges = s.selectedIntraExchanges ? new Set(s.selectedIntraExchanges) : new Set();
            this.forexRates = s.forexRates || {};
            this.selectedFiats = s.selectedFiats ? new Set(s.selectedFiats) : new Set();
            this.tradeLedger = s.tradeLedger ? s.tradeLedger.slice(-50) : [];
            this.liveTradeHistory = s.liveTradeHistory ? s.liveTradeHistory.slice(-20) : [];
            this.proxyMode = s.proxyMode || 'direct';
            this.customProxyUrl = s.customProxyUrl || '';
            this.execPath = s.execPath || '/execute';
            this.basketHoldings = s.basketHoldings || {};
            this.acquisitionPaths = s.acquisitionPaths || {};
            this.batchHistory = s.batchHistory ? s.batchHistory.slice(-20) : [];
            this.coinExchangeList = s.coinExchangeList || ['QUANTM_DEX'];
            this.stats.wsReconnects = s.wsReconnects || 0;
            this.lastCoinCreateTime = s.lastCoinCreateTime || 0;
            this.operationLatency = s.operationLatency ? s.operationLatency.slice(-10) : [];
            this.testnetsActive = s.testnetsActive || false;
            this.apiKeys = s.apiKeys || {};
            this.coinLevels = s.coinLevels || {};
          }
        } catch (e) { console.warn('State load error', e); }
        document.getElementById('solAddress').value = localStorage.getItem('wallet_sol') || '';
        document.getElementById('ethAddress').value = localStorage.getItem('wallet_eth') || '';
        document.getElementById('pumpToken').value = localStorage.getItem('pumpfun_token') || '';
        document.getElementById('basketInput').value = localStorage.getItem('basket') || 'USDT,BTC,ETH,DOGE,SHIB,SOL';
        document.getElementById('pathInput').value = localStorage.getItem('pathDepth') || 5;
        document.getElementById('pathSlider').value = document.getElementById('pathInput').value;
        document.getElementById('liveToggle').checked = this.liveMode;
        document.getElementById('liveTestnetToggle').checked = this.liveTestMode;
        document.getElementById('liveTestnetToggle').style.display = this.liveMode ? 'inline-block' : 'none';
        document.getElementById('testnetLabel').style.display = this.liveMode ? 'inline' : 'none';
        document.getElementById('proxySelect').value = this.proxyMode;
        document.getElementById('corsProxyUrl').value = this.customProxyUrl;
        document.getElementById('execPath').value = this.execPath;
        document.getElementById('walletProxyUrl').value = localStorage.getItem('walletProxyUrl') || '';
        document.getElementById('targetAssetsInput').value = localStorage.getItem('targetAssets') || '';
        document.getElementById('testnetToggle').checked = this.testnetsActive;
        UI.updateProfile();
        UI.renderFiatCheckboxes();
        UI.onProxyChange();
        UI.renderTradeLedger();
        UI.renderLiveTrades();
        UI.renderCoinLevels();
        UI.applyLevelConstraints();
        updateIntraExCheckboxes();
        UI.renderBasketTracker();
        UI.renderBatchHistory();
        UI.updateDashboard();
        UI.renderLatency();
      },
      save() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({
          bankroll: this.bankroll,
          paperMatrix: this.paperMatrix,
          liveMatrix: this.liveMatrix,
          paperLevel: this.paperLevel,
          liveLevel: this.liveLevel,
          liveMode: this.liveMode,
          liveTestMode: this.liveTestMode,
          userCoins: this.userCoins,
          selectedIntraExchanges: [...this.selectedIntraExchanges],
          forexRates: this.forexRates,
          selectedFiats: [...this.selectedFiats],
          tradeLedger: this.tradeLedger.slice(-50),
          liveTradeHistory: this.liveTradeHistory.slice(-20),
          proxyMode: this.proxyMode,
          customProxyUrl: this.customProxyUrl,
          execPath: this.execPath,
          basketHoldings: this.basketHoldings,
          acquisitionPaths: this.acquisitionPaths,
          batchHistory: this.batchHistory.slice(-20),
          coinExchangeList: this.coinExchangeList,
          wsReconnects: this.stats.wsReconnects,
          lastCoinCreateTime: this.lastCoinCreateTime,
          operationLatency: this.operationLatency.slice(-10),
          testnetsActive: this.testnetsActive,
          apiKeys: this.apiKeys,
          coinLevels: this.coinLevels,
        }));
        localStorage.setItem('wallet_sol', document.getElementById('solAddress').value);
        localStorage.setItem('wallet_eth', document.getElementById('ethAddress').value);
        localStorage.setItem('pumpfun_token', document.getElementById('pumpToken').value);
        localStorage.setItem('basket', document.getElementById('basketInput').value);
        localStorage.setItem('pathDepth', document.getElementById('pathInput').value);
        localStorage.setItem('walletProxyUrl', document.getElementById('walletProxyUrl').value);
        localStorage.setItem('targetAssets', document.getElementById('targetAssetsInput').value);
      },
      saveWallet() { this.save(); },
      savePumpToken() { this.save(); },

      // Ledger / tracking
      addTradeToLedger(opp, size, netProfit) {
        this.tradeLedger.unshift({ time: new Date().toISOString(), path: opp.path.join(' → '), size, profit: netProfit, type: opp.type, live: this.liveMode, testnet: this.liveTestMode });
        if (this.tradeLedger.length > 50) this.tradeLedger.length = 50;
        this.save();
        UI.renderTradeLedger();
        UI.updateDashboard();
      },
      addLiveTrade(opp, size, netProfit, txHash) {
        this.liveTradeHistory.unshift({ time: new Date().toISOString(), path: opp.path.join(' → '), size, profit: netProfit, txHash, status:'confirmed', testnet: this.liveTestMode });
        if (this.liveTradeHistory.length > 20) this.liveTradeHistory.length = 20;
        this.save();
        UI.renderLiveTrades();
      },
      recordBasketPurchase(asset, amount, pathDescription) {
        if (!this.basketHoldings[asset]) this.basketHoldings[asset] = 0;
        this.basketHoldings[asset] += amount;
        if (!this.acquisitionPaths[asset]) this.acquisitionPaths[asset] = [];
        this.acquisitionPaths[asset].push({ amount, path: pathDescription || 'unknown', time: new Date().toISOString() });
        this.save();
        UI.renderBasketTracker();
      },
      addBatchHistory(entry) {
        this.batchHistory.unshift(entry);
        if (this.batchHistory.length > 20) this.batchHistory.length = 20;
        this.save();
        UI.renderBatchHistory();
        UI.updateDashboard();
      },
      getAssetPrice(asset) {
        const stableTargets = ['USDT','USD','USDC','GUSD','BUSD'];
        for (const t of stableTargets) {
          const pair = this.allPairs.find(p => p.base === asset && p.target === t);
          if (pair) return pair.bidPrice || pair.price * 0.999;
        }
        const anyPair = this.allPairs.find(p => p.base === asset);
        if (anyPair) {
          const price = anyPair.bidPrice || anyPair.price * 0.999;
          if (!stableTargets.includes(anyPair.target)) {
            const tp = this.getAssetPrice(anyPair.target);
            if (tp > 0) return price * tp;
          }
          return price;
        }
        return 0;
      },
      computePurchasePower() {
        this.purchasePower = {};
        if (this.bankroll <= 0) return;
        const prices = {};
        for (const pair of this.allPairs) {
          if (!pair.base || !pair.target) continue;
          const ask = pair.askPrice || pair.price * 1.001;
          if (!prices[pair.base] || ask < prices[pair.base]) prices[pair.base] = ask;
        }
        for (const [asset, price] of Object.entries(prices)) {
          if (price > 0) this.purchasePower[asset] = this.bankroll / price;
        }
        for (const stable of ['USDT','USD','USDC','GUSD','BUSD']) {
          if (!this.purchasePower[stable]) this.purchasePower[stable] = this.bankroll;
        }
      },
      getTargetAssets() {
        const raw = document.getElementById('targetAssetsInput')?.value.trim();
        if (raw) return raw.split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
        return document.getElementById('basketInput').value.split(',').map(s => s.trim().toUpperCase()).filter(Boolean);
      },
      validateEdge(edge) { return edge && edge.rate > 0 && edge.rate < 1e6 && isFinite(edge.rate); },
      validateCycle(edges) {
        let p = 1;
        for (const e of edges) { if (!this.validateEdge(e)) return false; p *= e.rate; }
        return p > 0.5 && p < 100;
      },
      getMaxCoinExchanges() { return Math.min(1 + Math.floor(this.level / 3), 8); },
      getCoinCooldown() { if (this.level < 5) return Infinity; return Math.max(60, 300 - (this.level - 5) * 30); },
      getPullCooldown() { if (this.level <= 3) return 15000; if (this.level <= 6) return 12000; if (this.level <= 9) return 9000; return 6000; },
      getLiveScanInterval() { if (this.level < 2) return 60000; if (this.level < 5) return 45000; if (this.level < 8) return 30000; if (this.level < 10) return 15000; return 10000; },
      startAutoForex() {
        if (this.forexInterval) clearInterval(this.forexInterval);
        if (this.level >= 3 && this.selectedFiats.size > 0) {
          document.getElementById('forexAutoStatus').textContent = '🔄 Auto (5min)';
          this.forexInterval = setInterval(() => { if (!document.getElementById('scanBtn').disabled) fetchForexRates(); }, 300000);
        } else {
          document.getElementById('forexAutoStatus').textContent = '';
        }
      },
      allocateIndexFund(profit) {
        const pct = parseFloat(document.getElementById('indexFundPercent')?.value || 5) / 100;
        if (pct <= 0 || profit <= 0 || this.userCoins.length === 0) return;
        const amount = profit * pct;
        if (amount <= 0 || this.bankroll < amount) return;
        this.bankroll -= amount;
        const totalWeight = this.userCoins.reduce((sum, c) => sum + (this.coinLevels[c.symbol] || 1), 0);
        let r = Math.random() * totalWeight;
        for (const coin of this.userCoins) {
          const w = this.coinLevels[coin.symbol] || 1;
          r -= w;
          if (r <= 0) {
            const price = this.getAssetPrice(coin.symbol);
            if (price > 0) {
              const qty = amount / price;
              this.recordBasketPurchase(coin.symbol, qty, 'Index Fund (weighted)');
            }
            return;
          }
        }
      },
      addCoinXP(symbol, xp) {
