    }
    function rotateProxy() { currentProxyIndex = (currentProxyIndex + 1) % BUILTIN_PROXIES.length; UI.updateProxyStatus(); }

    async function smartFetch(url, options = {}, isCorsSafe = false) {
      if (isCorsSafe || State.proxyMode === 'direct') {
        try { const r = await fetch(url, options); if (r.ok) return r; if (r.status >= 400) throw new Error('HTTP '+r.status); } catch (e) {}
      }
      const proxy = getEffectiveProxyUrl();
      if (proxy) {
        try {
          const r = await fetch(proxy + encodeURIComponent(url), options);
          if (!r.ok) throw new Error('Proxy HTTP '+r.status);
          const text = await r.text();
          if (text.startsWith('<') || text.includes('corsdemo')) throw new Error('Non-JSON');
          try { return new Response(JSON.stringify(JSON.parse(text)), { status:200, headers:{'Content-Type':'application/json'} }); } catch { return new Response(text, { status:200, headers:{'Content-Type':'text/plain'} }); }
        } catch (e) { rotateProxy(); }
      }
      throw new Error('All fetch attempts exhausted');
    }

