    function parsePairSymbol(rawSymbol) {
      const s = (rawSymbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
      if (!s) return null;
      for (const q of KNOWN_QUOTES) {
        if (s.endsWith(q) && s.length > q.length) {
          const b = s.slice(0, s.length - q.length);
          if (b.length >= 1 && b !== q) return { base: b, target: q };
        }
      }
      const p = s.split(/[_-]/);
      if (p.length >= 2) return { base: p[0], target: p.slice(1).join('_') };
      return null;
    }

