    // ─── Graph Renderer (Canvas) ──────────────────
    class GraphRenderer {
      constructor(canvasId) {
        this.canvas = document.getElementById(canvasId);
        this.ctx = this.canvas.getContext('2d');
        this.nodes = {};
        this.edges = [];
        this.highlightedPaths = [];
        this.conflictEdges = new Set();
        this.animPhase = 0;
        this.purchasePower = {};
        this.maxPower = 1;
        this.pathColors = ['#ffd700','#ff00ff','#00ffaa','#ff4444','#4488ff','#ffaa00','#88ff88','#ff88ff'];
        this.resize();
        window.addEventListener('resize', () => this.resize());
      }
      resize() {
        const r = this.canvas.parentElement.getBoundingClientRect();
        const w = Math.min(700, r.width - 20);
        this.canvas.width = w;
        this.canvas.height = Math.min(380, w * 0.55);
      }
      buildFromGraph(graph, opps, power, paths, conflictEdges) {
        this.nodes = {};
        this.edges = [];
        this.purchasePower = power || {};
        this.highlightedPaths = paths || [];
        this.conflictEdges = conflictEdges || new Set();
        const seen = new Set();
        this.maxPower = Math.max(1, ...Object.values(this.purchasePower));
        for (const [b, tgts] of Object.entries(graph)) {
          if (!this.nodes[b]) this.nodes[b] = { id:b, x:0, y:0, power:this.purchasePower[b]||0, color:this.getColor(b), oppCount:0 };
          for (const [t, e] of Object.entries(tgts)) {
            const k = [b,t].sort().join('|');
            if (!seen.has(k)) {
              seen.add(k);
              this.edges.push({ from:b, to:t, vol:e.volume||0, liq:e.liquidity||0, rate:e.rate });
            }
            if (!this.nodes[t]) this.nodes[t] = { id:t, x:0, y:0, power:this.purchasePower[t]||0, color:this.getColor(t), oppCount:0 };
          }
        }
        if (opps) {
          for (const o of [...(opps.mega||[]), ...(opps.triangular||[]), ...(opps.bellman||[])]) {
            for (const n of o.path) { if (this.nodes[n]) this.nodes[n].oppCount++; }
          }
        }
        this.forceLayout();
        this.startAnim();
      }
      getColor(id) {
        const c = ['#ffd700','#00f0ff','#ff00ff','#00ffaa','#ff8888','#88ff88','#ffaa00','#aa88ff','#ff4488','#44ff88'];
        let h = 0;
        for (let i=0; i<id.length; i++) h = ((h<<5)-h) + id.charCodeAt(i);
        return c[Math.abs(h) % c.length];
      }
      forceLayout() {
        const nl = Object.values(this.nodes), n = nl.length;
        if (!n) return;
        const cx = this.canvas.width/2, cy = this.canvas.height/2;
        const rad = Math.min(cx,cy)*0.65;
        nl.forEach((nd,i) => { const a = (2*Math.PI*i)/n - Math.PI/2; nd.x = cx + rad*Math.cos(a); nd.y = cy + rad*Math.sin(a); });
        const iters = Math.min(35, Math.max(12, n));
        for (let iter=0; iter<iters; iter++) {
          for (let i=0; i<n; i++) {
            for (let j=i+1; j<n; j++) {
              const dx = nl[i].x - nl[j].x, dy = nl[i].y - nl[j].y;
              const d = Math.max(1, Math.sqrt(dx*dx+dy*dy));
              const f = 700/(d*d);
              nl[i].x += (dx/d)*f; nl[i].y += (dy/d)*f;
              nl[j].x -= (dx/d)*f; nl[j].y -= (dy/d)*f;
            }
          }
          for (const e of this.edges) {
            const from = this.nodes[e.from], to = this.nodes[e.to];
            if (!from || !to) continue;
            const dx = to.x - from.x, dy = to.y - from.y;
            const d = Math.max(1, Math.sqrt(dx*dx+dy*dy));
            const f = d * 0.0018;
            from.x += (dx/d)*f; from.y += (dy/d)*f;
            to.x -= (dx/d)*f; to.y -= (dy/d)*f;
          }
          for (const nd of nl) {
            nd.x += (cx - nd.x)*0.018; nd.y += (cy - nd.y)*0.018;
            nd.x = Math.max(15, Math.min(this.canvas.width-15, nd.x));
            nd.y = Math.max(15, Math.min(this.canvas.height-15, nd.y));
          }
        }
      }
      startAnim() {
        if (this.animRAF) cancelAnimationFrame(this.animRAF);
        const anim = () => { this.animPhase += 0.025; this.render(); this.animRAF = requestAnimationFrame(anim); };
        anim();
      }
      render() {
        const ctx = this.ctx, w = this.canvas.width, h = this.canvas.height;
        ctx.clearRect(0,0,w,h);
        ctx.strokeStyle = 'rgba(255,255,255,0.03)'; ctx.lineWidth = 1;
        for (let x=0; x<w; x+=35) { ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,h); ctx.stroke(); }
        for (let y=0; y<h; y+=35) { ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(w,y); ctx.stroke(); }
        const maxVol = Math.max(1, ...this.edges.map(e=>e.vol||0));
        const hlEdgesByPath = this.highlightedPaths.map(path => {
          const set = new Set();
          for (let i=0; i<path.length-1; i++) { set.add([path[i],path[i+1]].sort().join('|')); }
          return set;
        });
        for (const e of this.edges) {
          const from = this.nodes[e.from], to = this.nodes[e.to];
          if (!from || !to) continue;
          const ek = [e.from,e.to].sort().join('|');
          let highlighted = false, color = null, isConflict = false;
          for (let p=0; p<hlEdgesByPath.length; p++) {
            if (hlEdgesByPath[p].has(ek)) {
              if (highlighted) { isConflict = true; break; }
              highlighted = true;
              color = this.pathColors[p % this.pathColors.length];
            }
          }
          if (highlighted && isConflict) {
            ctx.strokeStyle = 'rgba(255,68,68,0.8)'; ctx.lineWidth = 2; ctx.setLineDash([5,3]); ctx.shadowColor = '#ff4444'; ctx.shadowBlur = 6;
          } else if (highlighted && color) {
            ctx.strokeStyle = color.replace(')',`,${0.7+0.3*Math.sin(this.animPhase*3)})`).replace('rgb','rgba');
            ctx.lineWidth = 2.5; ctx.setLineDash([]); ctx.shadowColor = color; ctx.shadowBlur = 8;
          } else {
            const alpha = Math.max(0.06, Math.min(0.45, (e.vol||0)/maxVol));
            ctx.strokeStyle = `rgba(0,240,255,${alpha})`; ctx.lineWidth = 1; ctx.setLineDash([]); ctx.shadowBlur = 0;
          }
          ctx.beginPath(); ctx.moveTo(from.x,from.y); ctx.lineTo(to.x,to.y); ctx.stroke();
          ctx.setLineDash([]); ctx.shadowBlur = 0;
        }
        for (const nd of Object.values(this.nodes)) {
          const inPaths = this.highlightedPaths.some(p => p.includes(nd.id));
          const pr = Math.min(1, (nd.power||0)/this.maxPower); const sz = 7 + pr*16;
          const ob = Math.min(7, (nd.oppCount||0)*1.8); const ts = sz + ob;
          const glow = ctx.createRadialGradient(nd.x,nd.y,0,nd.x,nd.y,ts*1.7);
          if (inPaths) { glow.addColorStop(0,'rgba(255,215,0,0.65)'); glow.addColorStop(0.5,'rgba(255,215,0,0.15)'); glow.addColorStop(1,'rgba(255,215,0,0)'); }
          else { glow.addColorStop(0,nd.color.replace(')',',0.45)').replace('rgb','rgba')); glow.addColorStop(1,'rgba(0,0,0,0)'); }
          ctx.fillStyle = glow; ctx.beginPath(); ctx.arc(nd.x,nd.y,ts*1.7,0,Math.PI*2); ctx.fill();
          const bg = ctx.createRadialGradient(nd.x-ts*0.25,nd.y-ts*0.25,ts*0.08,nd.x,nd.y,ts);
          bg.addColorStop(0,'#ffffff'); bg.addColorStop(0.3,nd.color); bg.addColorStop(1,'#000000');
          ctx.fillStyle = bg; ctx.beginPath(); ctx.arc(nd.x,nd.y,ts,0,Math.PI*2); ctx.fill();
          ctx.strokeStyle = inPaths ? '#ffd700' : 'rgba(255,255,255,0.25)'; ctx.lineWidth = inPaths ? 1.8 : 1; ctx.stroke();
          ctx.fillStyle = '#fff'; ctx.font = `${Math.max(7,ts*0.5)}px 'Courier New'`; ctx.textAlign = 'center';
          ctx.fillText(nd.id, nd.x, nd.y+ts+10);
        }
        for (let p=0; p<this.highlightedPaths.length; p++) {
          const path = this.highlightedPaths[p];
          if (path.length < 2) continue;
          const t = (this.animPhase + p*0.3) % 1;
          const idx = Math.floor(t*(path.length-1)), nxt = Math.min(idx+1,path.length-1);
          const from = this.nodes[path[idx]], to = this.nodes[path[nxt]];
          if (from && to) {
            const fr = (t*(path.length-1)) % 1;
            const px = from.x + (to.x-from.x)*fr, py = from.y + (to.y-from.y)*fr;
            const color = this.pathColors[p % this.pathColors.length];
            ctx.fillStyle = color; ctx.shadowColor = color; ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(px,py,4,0,Math.PI*2); ctx.fill(); ctx.shadowBlur = 0;
          }
        }
      }
    }

