    // ─── Forex fetching ────────────────────────────
    async function fetchForexRates() {
      const f = [...State.selectedFiats];
      if (!f.length) { log('No fiats selected','warning'); return; }
      let success = false;
      const trySource = async (url, parser, name) => {
        try {
          const r = await smartFetch(url, {}, true); const d = await r.json(); const rates = parser(d);
          if (rates && Object.keys(rates).length > 0) {
            State.forexRates = {}; f.forEach(cur => { if (rates[cur]) State.forexRates[cur] = rates[cur]; });
            success = true;
            document.getElementById('forexStatus').textContent = `✅ ${Object.keys(State.forexRates).length} rates (${name})`;
            log(`Forex: ${Object.keys(State.forexRates).length} from ${name}`,'success'); return true;
          }
        } catch(e) { log(`${name} failed: ${e.message}`,'warning'); }
        return false;
      };
      if (!await trySource('https://api.frankfurter.app/latest?from=USD', d => {
        const out = {}; if (d.rates) { for (const cur of f) { if (d.rates[cur]) out[cur] = 1/d.rates[cur]; } } return out;
      }, 'Frankfurter')) {
        if (!await trySource('https://open.er-api.com/v6/latest/USD', d => {
          const out = {}; if (d.rates) { for (const cur of f) { if (d.rates[cur]) out[cur] = 1/d.rates[cur]; } } return out;
        }, 'ExchangeRate')) {
          if (!await trySource(`https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd,${f.join(',')}`, d => {
            const out = {}; if (d.bitcoin?.usd) { const bu = d.bitcoin.usd; f.forEach(cur => { if (d.bitcoin[cur]) out[cur] = bu / d.bitcoin[cur]; }); } return out;
          }, 'CoinGecko')) {
            const fb = { RUB:0.012, INR:0.012, EUR:1.08, GBP:1.26, JPY:0.0067, CNY:0.14, KRW:0.00076, AUD:0.64, CAD:0.73, CHF:1.12, AED:0.27, TRY:0.032, BRL:0.18, SGD:0.74, PLN:0.23 };
            State.forexRates = {}; f.forEach(cur => { if (fb[cur]) State.forexRates[cur] = fb[cur]; });
            document.getElementById('forexStatus').textContent = `✅ ${Object.keys(State.forexRates).length} (cached)`;
            log('Forex: using hardcoded cache','warning');
          }
        }
      }
      State.save(); displayLowValue();
    }

    function getUsdPrice(p) {
      if (!p) return 0;
      if (['USDT','USD','USDC','BUSD','GUSD'].includes(p.target)) return p.price;
      const r = State.forexRates[p.target]; return r ? p.price * r : p.price;
    }
    function toUsd(a, c) {
      if (!c || ['USDT','USD','USDC','BUSD','GUSD'].includes(c)) return a;
      const r = State.forexRates[c]; return r ? a * r : a;
    }

    // ─── API loading ──────────────────────────────
    async function loadApi(defKey) {
      const ex = State.exchanges[defKey];
      const isCors = CORS_OK_EXCHANGES.has(defKey);
      try {
        let h = {};
        if (ex.auth) { const t = document.getElementById('pumpToken').value.trim(); if (t) h = {'Authorization': 'Bearer '+t}; }
        const r = await smartFetch(ex.url, { headers: h }, isCors);
        if (!r.ok) throw new Error('HTTP '+r.status);
        const d = await r.json();
        let pairs = [];
        switch (ex.parser) {
          case 'okx': pairs = (d.data||[]).slice(0,600).map(t=>{ const p = t.instId.split('-'); if (p.length!==2) return null; const pr = parseFloat(t.last)||0, v = (parseFloat(t.volCcy24h)||0)*pr; return { base:p[0], target:p[1], price:pr, volume:v, liquidity:v, bidPrice:parseFloat(t.bidPx)||pr*0.999, askPrice:parseFloat(t.askPx)||pr*1.001, exchange:defKey, exchangeType:'cex' }; }).filter(Boolean); break;
          case 'coinbase': pairs = (Array.isArray(d)?d:[]).slice(0,300).map(p=>{ const pr = parseFloat(p.price)||1, v = (parseFloat(p.volume)||0)*pr; return { base:p.base_currency, target:p.quote_currency, price:pr, volume:v, liquidity:v, bidPrice:pr*0.998, askPrice:pr*1.002, exchange:defKey, exchangeType:'cex' }; }).filter(p=>p.price>0); break;
          case 'binance': pairs = (Array.isArray(d)?d:[]).slice(0,600).map(t=>{ const pr = parseFloat(t.lastPrice)||0, v = (parseFloat(t.quoteVolume)||0)*pr; const ps = parsePairSymbol(t.symbol||''); if (!ps) return null; return { base:ps.base, target:ps.target, price:pr, volume:v, liquidity:v, bidPrice:parseFloat(t.bidPrice)||pr*0.999, askPrice:parseFloat(t.askPrice)||pr*1.001, exchange:defKey, exchangeType:'cex' }; }).filter(p=>p&&p.price>0&&p.base&&p.base!==p.target); break;
          case 'kucoin': pairs = (d?.data?.ticker||[]).slice(0,500).map(t=>{ const pr = parseFloat(t.last)||0, v = (parseFloat(t.volValue)||0)*pr; const ps = parsePairSymbol(t.symbol||''); if (!ps) return null; return { base:ps.base, target:ps.target, price:pr, volume:v, liquidity:v, bidPrice:parseFloat(t.buy)||pr*0.999, askPrice:parseFloat(t.sell)||pr*1.001, exchange:defKey, exchangeType:'cex' }; }).filter(p=>p&&p.price>0&&p.base); break;
          case 'kraken': { const result = d?.result||{}; pairs = Object.keys(result).slice(0,300).map(k=>{ const t = result[k]; const pr = parseFloat(t.c?.[0])||0, v = (parseFloat(t.v?.[1])||0)*pr; const ps = parsePairSymbol(k); if (!ps) return null; return { base:ps.base, target:ps.target, price:pr, volume:v, liquidity:v, bidPrice:parseFloat(t.b?.[0])||pr*0.999, askPrice:parseFloat(t.a?.[0])||pr*1.001, exchange:defKey, exchangeType:'cex' }; }).filter(p=>p&&p.price>0); } break;
          case 'bitstamp': pairs = (Array.isArray(d)?d:[]).slice(0,250).map(t=>{ const pr = parseFloat(t.last)||0, v = (parseFloat(t.volume)||0)*pr; const ps = (t.pair||'').split('/'); return { base:ps[0]||'', target:ps[1]||'USD', price:pr, volume:v, liquidity:v, bidPrice:parseFloat(t.bid)||pr*0.999, askPrice:parseFloat(t.ask)||pr*1.001, exchange:defKey, exchangeType:'cex' }; }).filter(p=>p.price>0&&p.base); break;
          case 'gemini': pairs = (Array.isArray(d)?d:[]).map(t=>{ const ps = parsePairSymbol(t.pair||t.symbol||''); if (!ps) return null; const pr = parseFloat(t.price)||0; return { base:ps.base, target:ps.target, price:pr, volume:0, liquidity:pr*100000, bidPrice:pr*0.998, askPrice:pr*1.002, exchange:defKey, exchangeType:'cex' }; }).filter(p=>p&&p.price>0&&p.base!==p.target&&p.liquidity>=50); break;
          case 'dexscreener': { const raw = d?.pairs||[]; pairs = raw.slice(0,400).map(p=>{ const pr = parseFloat(p.priceUsd)||0, liq = p.liquidity?.usd||0; const sp = liq>0?Math.max(0.003,Math.min(0.05,5000/liq)):0.03; return { base:p.baseToken?.symbol||'?', target:p.quoteToken?.symbol||'ETH', price:pr, volume:p.volume?.h24||0, liquidity:liq, bidPrice:pr*(1-sp/2), askPrice:pr*(1+sp/2), exchange:defKey, exchangeType:'dex' }; }).filter(p=>p.base!=='?'&&p.price>0); } break;
          case 'coingecko': pairs = (Array.isArray(d)?d:[]).slice(0,250).map(c=>({ base:(c.symbol||'').toUpperCase(), target:'USD', price:c.current_price||0, volume:c.total_volume||0, liquidity:c.market_cap||0, bidPrice:(c.current_price||0)*0.999, askPrice:(c.current_price||0)*1.001, exchange:defKey, exchangeType:'info' })).filter(p=>p.price>0); break;
          default: pairs = [];
        }
        pairs = pairs.filter(p=>p&&p.base&&p.target&&p.base!==p.target&&p.price>0&&p.price<1e15);
        ex.pairs = pairs; ex.status = 'online'; log(`${ex.name}: ${pairs.length}p`,'success');
      } catch (e) {
        // fallback to DexScreener for some testnet/defi
        if (['pumpfun','pumpfun_dev','uniswap_sepolia','sushi_test'].includes(defKey)) {
          try {
            const fr = await smartFetch('https://api.dexscreener.com/latest/dex/search?q=ETH', {}, true);
            const fd = await fr.json();
            ex.pairs = (fd?.pairs||[]).slice(0,400).map(p=>{ const pr = parseFloat(p.priceUsd)||0, liq = p.liquidity?.usd||0; const sp = liq>0?Math.max(0.003,Math.min(0.05,5000/liq)):0.03; return { base:p.baseToken?.symbol||'?', target:p.quoteToken?.symbol||'ETH', price:pr, volume:p.volume?.h24||0, liquidity:liq, bidPrice:pr*(1-sp/2), askPrice:pr*(1+sp/2), exchange:defKey, exchangeType:'dex' }; }).filter(p=>p.base!=='?'&&p.price>0);
            ex.status = 'online'; log(`DEX fb: ${ex.pairs.length}p`,'success'); return;
          } catch (fb) {}
        }
        ex.status = 'offline'; ex.pairs = [];
        log(`${ex.name}: ${e.message}`,'error');
        if (State.proxyMode === 'builtin') rotateProxy();
      }
    }

    // ─── System initialization ────────────────────
    async function initSystem() {
      log('🎰 Initializing...'); updateStatus('🔄 LOADING...');
      UI.updateProxyStatus();
      const start = performance.now();
      await Promise.allSettled(exchangeDefs.map(d => loadApi(d.key)));
      if (State.testnetsActive) { await Promise.allSettled(testnetExchangeDefs.map(d => loadApi(d.key))); }
      State.allPairs = Object.values(State.exchanges).flatMap(e => e.pairs);
      State.userCoins.forEach(c => {
        const q = c.quote || 'USDT';
        State.allPairs.push({ base:c.symbol, target:q, price:c.price, volume:c.liq*0.3, liquidity:c.liq, bidPrice:c.price*0.95, askPrice:c.price*1.05, exchange:c.exchange||'QUANTM_DEX', exchangeType:'dex' });
      });
      State.stats.totalPairs = State.allPairs.length;
      State.computePurchasePower();
      updateIntraExCheckboxes();
      buildGraph(); buildTriangles(); displayLowValue();
      updateExchangeDisplay(); updateStats();
      const on = Object.values(State.exchanges).filter(e => e.status === 'online').length;
      if (on > 0) { document.getElementById('scanBtn').disabled = false; updateStatus(`✅ READY · ${on}/${exchangeDefs.length+(State.testnetsActive?testnetExchangeDefs.length:0)} online`); }
      else updateStatus('❌ NO EXCHANGES ONLINE');
      State.operationLatency.push({ op:'INIT', duration:Math.round(performance.now()-start) });
      UI.renderLatency(); State.save();
      if (!Object.keys(State.forexRates).length && State.selectedFiats.size) { log('Auto‑fetching forex…'); await fetchForexRates(); }
      State.startAutoForex();
      if (document.getElementById('graphSlotContainer').style.display === 'block') {
        if (!State.graphRenderer) State.graphRenderer = new GraphRenderer('graphNetwork');
        State.graphRenderer.buildFromGraph(State.graph, State.opportunities, State.purchasePower, State.highlightedPaths, State.conflictEdges||new Set());
      }
      UI.applyLevelConstraints();
    }

    function updateStatus(m) { document.getElementById('mainStatus').textContent = m; }

    function getGraphPairs() {
      const m = document.getElementById('arbMode').value;
      if (m === 'intra') return [...State.selectedIntraExchanges].flatMap(k => State.exchanges[k]?.pairs || []);
      return Object.values(State.exchanges).filter(e => e.status==='online' && e.parser!=='coingecko' && e.parser!=='coinlore').flatMap(e => e.pairs);
    }

    function applyWsCache(p) {
      const c = State.wsTickers[p.exchange];
      if (c) { const k = `${p.base}${p.target}`.toUpperCase(); const t = c[k]; if (t) return { ...p, bidPrice:t.bid||p.bidPrice, askPrice:t.ask||p.askPrice }; }
      return p;
    }

    function sanitizeRate(r) { if (!isFinite(r)||r<=0) return 0; if (r>1e12) return 1e12; if (r<1e-15) return 1e-15; return r; }

    function buildGraph() {
      State.graph = {};
      const pairs = getGraphPairs().map(applyWsCache);
      pairs.forEach(p => {
        if (p.liquidity < 50) return;
        if (!p.base || !p.target || p.base===p.target) return;
        if (!State.graph[p.base]) State.graph[p.base] = {};
        if (!State.graph[p.target]) State.graph[p.target] = {};
        const r1 = sanitizeRate(p.bidPrice), r2 = sanitizeRate(1/p.askPrice);
        if (r1>0) State.graph[p.base][p.target] = { rate:r1, weight:-Math.log(r1), volume:p.volume, liquidity:p.liquidity, exchange:p.exchange, exchangeType:p.exchangeType, short:false };
        if (r2>0) State.graph[p.target][p.base] = { rate:r2, weight:-Math.log(r2), volume:p.volume, liquidity:p.liquidity, exchange:p.exchange, exchangeType:p.exchangeType, short:true };
      });
      State.stats.graphNodes = Object.keys(State.graph).length;
      State.stats.graphEdges = Object.values(State.graph).reduce((s,o)=>s+Object.keys(o).length,0);
    }

    function buildTriangles() {
      State.triangles = []; const ns = Object.keys(State.graph); const seen = new Set();
      for (let i=0; i<Math.min(ns.length,150); i++) {
        const A = ns[i]; const nA = Object.keys(State.graph[A]||{});
        for (const B of nA) {
          const nB = Object.keys(State.graph[B]||{});
          for (const C of nB) {
            if (State.graph[C]?.[A]) { const canon = [A,B,C].sort().join('|'); if (!seen.has(canon)) { seen.add(canon); State.triangles.push([A,B,C]); } }
          }
        }
      }
      State.stats.triangleCount = State.triangles.length;
    }

    function displayLowValue() {
      const all = State.allPairs.filter(p => p.price>0);
      const fmt = p => { const u = getUsdPrice(p).toExponential(4); let t = ''; if (getUsdPrice(p)<1e-15) t='PLANCK'; else if (getUsdPrice(p)<1e-12) t='FEMTO'; else if (getUsdPrice(p)<1e-9) t='PICO'; return `<div>${p.base} $${u} <span class="tier-badge tier-${t.toLowerCase()}">${t}</span></div>`; };
      document.getElementById('picoValue').innerHTML = all.filter(p=>getUsdPrice(p)<1e-9&&getUsdPrice(p)>=1e-12).slice(0,25).map(fmt).join('')||'None';
      document.getElementById('femtoValue').innerHTML = all.filter(p=>getUsdPrice(p)<1e-12&&getUsdPrice(p)>=1e-15).slice(0,25).map(fmt).join('')||'None';
      document.getElementById('planckValue').innerHTML = all.filter(p=>getUsdPrice(p)<1e-15).slice(0,25).map(fmt).join('')||'None';
    }

    // ─── Opportunity scanning ─────────────────────
    function scanTriangular(minP=0.0001) {
      const opps = [], inv = 1000;
      const mode = document.getElementById('arbMode').value;
      State.triangles.forEach(([A,B,C]) => {
        const orders = [[A,B,C,A],[B,C,A,B],[C,A,B,C]];
        for (const [s,m1,m2,e] of orders) {
          const e1 = State.graph[s]?.[m1], e2 = State.graph[m1]?.[m2], e3 = State.graph[m2]?.[e];
          if (!e1||!e2||!e3) continue;
          if (!State.validateCycle([e1,e2,e3])) continue;
          if (mode==='intra') { const exs = new Set([e1.exchange,e2.exchange,e3.exchange]); if (exs.size!==1 || !State.selectedIntraExchanges.has(e1.exchange)) continue; }
          const final = inv * e1.rate * e2.rate * e3.rate;
          const profit = final - inv, pct = (profit/inv)*100;
          if (pct>=minP && pct<50) {
            const ms = Math.min(e1.liquidity,e2.liquidity,e3.liquidity)*0.05;
            opps.push({ type:'triangular', path:[s,m1,m2,e], profitPercent:pct, actualProfit:toUsd((ms/inv)*profit,s), maxTradeSize:toUsd(ms,s), edges:[e1,e2,e3] });
          }
        }
      });
      return opps;
    }

    function bellmanFord(start, depth=5) {
      const cs = Object.keys(State.graph);
      if (!cs.includes(start)) return [];
      const mode = document.getElementById('arbMode').value;
      const dist = {}, pred = {};
      cs.forEach(c => { dist[c]=Infinity; pred[c]=null; });
      dist[start] = 0;
      for (let i=0; i<Math.min(depth-1, cs.length-1); i++) {
        let upd = false;
        for (const u of cs) {
          const nb = State.graph[u]; if (!nb) continue;
          for (const v in nb) {
            const w = nb[v].weight;
            if (dist[u]!==Infinity && dist[u]+w < dist[v]) {
              if (mode==='intra' && !State.selectedIntraExchanges.has(nb[v].exchange)) continue;
              dist[v] = dist[u]+w; pred[v] = u; upd = true;
            }
          }
        }
        if (!upd) break;
      }
      const opps = [];
      const target = State.getTargetAssets();
      for (const u of cs) {
        const nb = State.graph[u]; if (!nb) continue;
        for (const v in nb) {
          if (dist[u]!==Infinity && dist[u]+nb[v].weight < dist[v]) {
            const cyc = (() => {
              const c = [v]; let cur = v; const vis = new Set(); vis.add(v);
              for (let i=0; i<depth; i++) { cur = pred[cur]; if (!cur) return null; c.push(cur); if (cur===start) return c; if (vis.has(cur)) return null; vis.add(cur); }
              return null;
            })();
            if (cyc && cyc[0]===start && target.includes(start)) {
              let amt = 1000; const edges = []; let tl = Infinity;
              for (let i=0; i<cyc.length-1; i++) { const e = State.graph[cyc[i]]?.[cyc[i+1]]; if (!e) break; amt *= e.rate; edges.push(e); tl = Math.min(tl, e.liquidity); }
              const le = State.graph[cyc[cyc.length-1]]?.[cyc[0]];
              if (le && tl>=50 && State.validateCycle([...edges, le])) {
                amt *= le.rate; edges.push(le); tl = Math.min(tl, le.liquidity);
                const p = amt-1000, pc = (p/1000)*100;
                if (pc>=0.0001 && pc<50) {
                  const ms = Math.min(...edges.map(e=>e.liquidity))*0.05;
                  opps.push({ type:'bellman-ford', path:[...cyc,cyc[0]], profitPercent:pc, actualProfit:toUsd((ms/1000)*p,start), maxTradeSize:toUsd(ms,start), edges });
                }
              }
            }
          }
        }
      }
      return opps;
    }

    // ─── WebSocket connections ────────────────────
    function connectAllWebSockets() {
