              log(`📡 ${exKey} WS connected`,'success'); State.exchanges[exKey].wsStatus = 'live';
              if (exKey==='okx') ws.send(JSON.stringify({op:'subscribe',args:[{channel:'tickers',instType:'SPOT'}]}));
              if (exKey==='bybit') ws.send(JSON.stringify({op:'subscribe',args:['tickers.BTCUSDT']}));
              if (exKey==='kraken') ws.send(JSON.stringify({event:'subscribe',pair:['XBT/USD','ETH/USD'],subscription:{name:'ticker'}}));
              if (exKey==='coinbase') ws.send(JSON.stringify({type:'subscribe',product_ids:['BTC-USD','ETH-USD'],channels:['ticker']}));
              updateExchangeDisplay();
            };
            ws.onmessage = onMessage;
            ws.onclose = () => {
