              State.exchanges[exKey].wsStatus = 'reconnecting'; State.stats.wsReconnects++;
              UI.updateProfile(); updateExchangeDisplay(); setTimeout(connect, retryDelay);
            };
            ws.onerror = () => { ws.close(); };
            State.wsConnections[exKey] = ws;
          } catch (e) { setTimeout(connect, retryDelay); }
        };
        connect();
      };
      createWS('wss://ws.okx.com:8443/ws/v5/public', e => {
