line-block':'none';document.getElementById('testnetLabel').style.display=this.liveMode?'inline':'none';document.getElementById('proxySelect').value=this.proxyMode;document.getElementById('corsProxyUrl').value=this.customProxyUrl;document.getElementById('execPath').value=this.execPath;document.getElementById('walletProxyUrl').value=localStorage.getItem('walletProxyUrl')||'';document.getElementById('targetAssetsInput').value=localStorage.getItem('targetAssets')||'';document.getElementById('testnetToggle').checked=this.testnetsActive;UI.updateProfile();UI.renderFiatCheckboxes();UI.onProxyChange();UI.renderTradeLedger();UI.renderLiveTrades();UI.renderCoinLevels();UI.applyLevelConstraints();updateIntraExCheckboxes();UI.renderBasketTracker();UI.renderBatchHistory();UI.updateDashboard();UI.renderLatency();},
