        const d = await r.json();
        if (d && d.rates) {
          State.forexRates = {};
          for (const cur of f) {
            if (d.rates[cur]) State.forexRates[cur] = 1 / d.rates[cur];
          }
          if (Object.keys(State.forexRates).length > 0) {
            success = true;
            document.getElementById('forexStatus').textContent =
              `✅ ${Object.keys(State.forexRates).length} rates (ExchangeRate)`;
            log(`Forex: ${Object.keys(State.forexRates).length} from ExchangeRate`,'success');
          }
        }
      } catch (e) { log('ExchangeRate failed: '+e.message,'warning'); }

      if (!success) {
        // Fallback: Frankfurter
        try {
          const r = await smartFetch('https://api.frankfurter.app/latest?from=USD', {}, true);
          const d = await r.json();
          if (d && d.rates) {
            State.forexRates = {};
            for (const cur of f) { if (d.rates[cur]) State.forexRates[cur] = 1 / d.rates[cur]; }
